231: /**
232:  * One effect: a strip, drawn about its own origin, already running.
233:  *
234:  * The board plays this the moment it appears and takes it away when it is done, so
235:  * `playing` is the whole of its animation policy — there is nobody to tell it to
236:  * start. It used to be a self-describing `<image>` whose clips the renderer found
237:  * by class name and read out of a JSON attribute, then played whichever came first.
238:  */
239: export function candidate01FxPicture(topic: string): BoardPicture {
240:   const record = candidate01Asset(topic);
241:   const frameWidth = record.frameWidth ?? 32;
242:   const frameHeight = record.frameHeight ?? 32;
243:   const frames = record.frames ?? 1;
244:   const anchor = record.anchor;
245:   if (!anchor || anchor.length !== 2
246:     || !Number.isFinite(anchor[0]) || anchor[0] < 0 || anchor[0] >= frameWidth
247:     || !Number.isFinite(anchor[1]) || anchor[1] < 0 || anchor[1] >= frameHeight) {
248:     throw new Error(`candidate-01 effect has no valid anchor: ${topic}`);
249:   }
250:   return {
251:     body: '',
252:     strip: {
253:       href: record.url,
254:       frameWidth,
255:       frameHeight,
256:       frameCount: frames,
257:       x: -anchor[0],
258:       y: -anchor[1],
259:       clips: [{
260:         id: 'effect',
261:         frames: Array.from({ length: frames }, (_, frame) => frame),
262:         fps: record.fps ?? 12,
263:         loop: record.loop ?? false,
264:       }],
265:       playing: 'effect',
266:     },
267:   };
268: }

198: function resolveRuntimeUrl(record: Candidate01AssetRecord): string {
199:   const hd = runtimeHdTopics.get(record.topicId);
200:   if (hd) {
201:     validateCandidate01HdAsset(record, hd);
202:     const hdUrl = runtimeHdFiles[`${packRoot}${hd.png}`];
203:     if (!hdUrl) throw new Error(`candidate-01 runtime HD asset is missing from the Vite graph: ${record.topicId}`);
204:     return hdUrl;
205:   }
206:   const url = runtimeFiles[`${packRoot}${record.png}`];
207:   if (!url) throw new Error(`candidate-01 asset is missing from the Vite graph: ${record.topicId} (${record.png})`);
208:   return url;
209: }
