181:   play(id: string, clipId: string, restart = true): void {
182:     const track = this.track(id);
183:     const clip = track.clips.get(clipId);
184:     if (!clip) throw new Error(`unknown frame animation clip: ${clipId}`);
185:     if (!restart && track.clip?.id === clipId) return;
186:     track.clip = clip;
187:     track.startedAt = this.driver.now();
188:     this.applyFrame(track, clip.frames[0]);
189:     if (!this.motionEnabled()) {
190:       track.clip = null;
191:       this.pauseLoopIfIdle();
192:       return;
193:     }
194:     if (clip.frames.length > 1) this.ensureLoop();
195:   }
196: 
197:   stop(id: string, frame?: number): void {
198:     const track = this.track(id);
199:     track.clip = null;
200:     if (frame !== undefined) {
201:       if (!Number.isInteger(frame) || frame < 0 || frame >= track.target.frameCount) {
202:         throw new Error(`invalid stopped frame ${frame}`);
203:       }
204:       this.applyFrame(track, frame);
205:     }
206:     this.pauseLoopIfIdle();
207:   }
