215:   private readonly tick = (now: number): void => {
216:     this.requestHandle = null;
217:     for (const track of this.tracks.values()) {
218:       const clip = track.clip;
219:       if (!clip || clip.frames.length < 2) continue;
220:       const elapsedFrames = Math.max(0, Math.floor(((now - track.startedAt) * clip.fps) / 1000));
221:       if (!clip.loop && elapsedFrames >= clip.frames.length) {
222:         this.applyFrame(track, clip.frames[clip.frames.length - 1]);
223:         track.clip = null;
224:         continue;
225:       }
226:       const index = clip.loop ? elapsedFrames % clip.frames.length : elapsedFrames;
227:       this.applyFrame(track, clip.frames[index]);
228:     }

205:   private draw(strip: BoardStrip): void {
206:     const window = fromMarkup(boardStripMarkup(strip)).firstElementChild as SVGSVGElement;
207:     this.figure.append(window);
208:     this.selectSource(window);
209:     this.animations.register(this.id, {
210:       frameCount: strip.frameCount,
211:       setFrame: (frame) => {
212:         setAttrs(window, { viewBox: boardStripWindow(strip, frame) });
213:         this.syncSelectionCue();
214:       },
215:     }, strip.clips);
216:     this.playing = true;
217:     if (strip.playing) this.animations.play(this.id, strip.playing);
218:   }
